def delete_ftp_dir_recursive(ftp, target_dir):
    try:
        ftp.cwd(target_dir)
    except ftplib.error_perm:
        # Directory doesn't exist
        return

    names = ftp.nlst()
    for name in names:
        if name in [".", ".."]:
            continue
        try:
            ftp.delete(name)
            print(f"Deleted file: {target_dir}/{name}")
        except ftplib.error_perm:
            # It's a directory
            delete_ftp_dir_recursive(ftp, f"{target_dir}/{name}")

    ftp.cwd("..")
    try:
        ftp.rmd(target_dir)
        print(f"Deleted directory: {target_dir}")
    except Exception as e:
        print(f"Failed to remove directory {target_dir}: {e}")

def make_dirs_recursive(ftp, remote_dir):
    parts = [p for p in remote_dir.split('/') if p]
    path = ''
    for part in parts:
        path += '/' + part
        try:
            ftp.cwd(path)
        except ftplib.error_perm:
            try:
                ftp.mkd(path)
            except ftplib.error_perm:
                pass

def upload_directory(ftp, local_dir, remote_dir):
    make_dirs_recursive(ftp, remote_dir)
    ftp.cwd(remote_dir)

    for item in os.listdir(local_dir):
        local_path = os.path.join(local_dir, item)
        if os.path.isfile(local_path):
            with open(local_path, "rb") as f:
